contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Send some amount to c.go and assert owner is unchanged (in address equality)
    // and that interpreted as uint256 it does not increase (redundant but expressed numerically).
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 ownerBeforeUint = uint256(uint160(ownerBefore));

        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 ownerAfterUint = uint256(uint160(ownerAfter));

        // General invariant: owner address is unchanged by go, and its numeric value does not increase.
        assert(ownerAfter == ownerBefore && ownerAfterUint <= ownerBeforeUint);
    }

    receive() external payable {}
}

